public class SimpleWriteAheadLog {
    private final FileChannel logChannel;
    private final ByteBuffer writeBuffer;
    private long currentLSN = 0;

    public synchronized long appendEntry(byte[] recordData) throws IOException {
        long lsn = ++currentLSN;
        int recordSize = 8 + 4 + recordData.length; // LSN + Length + Payload

        writeBuffer.clear();
        writeBuffer.putLong(lsn);
        writeBuffer.putInt(recordData.length);
        writeBuffer.put(recordData);
        writeBuffer.flip();

        while (writeBuffer.hasRemaining()) {
            logChannel.write(writeBuffer);
        }
        logChannel.force(false); // Force fsync to guarantee durability
        return lsn;
    }
}
